// Package logfile persists event batches as an append-only sequence of
// length-prefixed, CRC-checked frames.
//
// Frame layout (all integers big-endian):
//
//	[4 bytes payload length][4 bytes CRC32-IEEE of payload][payload bytes]
//
// The payload is a JSON array encoded with events.MarshalBatch.
package logfile

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"

	"github.com/cocosolocoder/signalroom/internal/events"
)

const (
	logName  = "events.log"
	lockName = "lock"
)

// Log is an append-only, concurrency-safe frame writer holding an exclusive
// directory lock for its lifetime.
type Log struct {
	*frameLog
	lockFile *os.File
	key      []byte
}

// Open acquires an exclusive lock on the data directory, creates it if
// needed, replays the log, and truncates at most one incomplete trailing
// frame (a torn final write). A corrupt frame in the middle, or a complete
// frame containing illegal data, is fatal: Open returns an error without
// modifying the file.
//
// Recovered batches are returned in write order, ready to load into a
// timeline.
func Open(dir string) (*Log, [][]events.Event, error) {
	if dir == "" {
		return nil, nil, errors.New("data directory is required")
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, nil, fmt.Errorf("create data directory: %w", err)
	}

	lockPath := filepath.Join(dir, lockName)
	lockFile, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
	if err != nil {
		return nil, nil, fmt.Errorf("open directory lock: %w", err)
	}
	if err := tryLock(lockFile); err != nil {
		lockFile.Close()
		if errors.Is(err, errLocked) {
			return nil, nil, fmt.Errorf("data directory %q is in use by another signalroom instance", dir)
		}
		return nil, nil, fmt.Errorf("acquire directory lock: %w", err)
	}

	base, batches, err := openFrameLog(dir, logName, "event", "batch", decodeEventBatch)
	if err != nil {
		unlock(lockFile)
		lockFile.Close()
		return nil, nil, err
	}

	key, err := loadOrCreateKey(dir)
	if err != nil {
		base.Close()
		unlock(lockFile)
		lockFile.Close()
		return nil, nil, err
	}

	return &Log{frameLog: base, lockFile: lockFile, key: key}, batches, nil
}

// decodeEventBatch decodes one frame payload into a validated, normalized
// event batch. An empty batch or an invalid event is rejected as corruption.
func decodeEventBatch(payload []byte) ([]events.Event, error) {
	batch, err := events.DecodeBatch(payload)
	if err != nil {
		return nil, err
	}
	if len(batch) == 0 {
		return nil, errors.New("empty batch frame")
	}
	for i := range batch {
		normalized, err := events.Normalize(batch[i])
		if err != nil {
			return nil, err
		}
		batch[i] = normalized
	}
	return batch, nil
}

// Append durably writes one batch. The bytes hit the disk (write followed by
// fsync) before Append returns. Any write or sync failure poisons the log:
// this call and every later one return ErrPoisoned until restart.
func (l *Log) Append(batch []events.Event) error {
	payload, err := events.MarshalBatch(batch)
	if err != nil {
		return fmt.Errorf("encode batch: %w", err)
	}
	return l.appendFrame(payload)
}

// Close releases the log and the exclusive directory lock.
func (l *Log) Close() error {
	l.mu.Lock()
	defer l.mu.Unlock()
	var closeErr error
	if err := l.file.Close(); err != nil {
		closeErr = err
	}
	if err := unlock(l.lockFile); err != nil && closeErr == nil {
		closeErr = err
	}
	if err := l.lockFile.Close(); err != nil && closeErr == nil {
		closeErr = err
	}
	return closeErr
}

package logfile

import (
	"encoding/binary"
	"errors"
	"fmt"
	"hash/crc32"
	"os"
	"path/filepath"
	"sync"
)

const (
	headerSize = 8
	// MaxPayloadBytes is the 64 MiB (1024*1024-byte units) capacity of one
	// frame payload. It bounds the saved content itself, excluding the
	// 8-byte frame header, and guards against absurd allocations when a
	// corrupt length prefix happens to point inside the file.
	MaxPayloadBytes = 64 << 20
)

// ErrPayloadTooLarge is returned when a frame's encoded content exceeds
// MaxPayloadBytes. It describes the content, not a storage fault: the check
// runs before anything is written or locked for mutation, the log is not
// poisoned, and later writes keep working without a restart.
var ErrPayloadTooLarge = errors.New("frame payload exceeds the 64 MiB save capacity")

// ErrPoisoned is returned after a write or sync failure. The log refuses all
// further writes until the process is restarted and recovery succeeds.
var ErrPoisoned = errors.New("log is unavailable after a storage failure")

// CorruptionError marks a complete frame that fails its checksum or contains
// illegal data, as opposed to an incomplete trailing frame.
type CorruptionError struct{ Reason string }

func (e *CorruptionError) Error() string { return e.Reason }

func corruption(format string, args ...any) error {
	return &CorruptionError{Reason: fmt.Sprintf(format, args...)}
}

// frameLog is the shared append-only frame writer behind the event, incident,
// and metric logs. It owns the frame layout, torn-tail recovery, and the
// poison-on-failure write path; each concrete log supplies only its own
// payload encoding and content validation, so the durability rule lives in
// exactly one place.
type frameLog struct {
	mu       sync.Mutex
	file     *os.File
	dir      string
	noun     string // the log's name in error messages: "event", "incident", "metrics"
	unit     string // what one frame holds: "batch", "incident record", "metric batch"
	poisoned bool
}

// openFrameLog opens (creating if absent) the named log inside an
// already-locked data directory, replays its frames with decode, and
// truncates at most one incomplete trailing frame. A corrupt frame in the
// middle, or a complete frame whose payload decode rejects, is fatal and
// leaves the file untouched.
func openFrameLog[T any](dir, name, noun, unit string, decode func(payload []byte) (T, error)) (*frameLog, []T, error) {
	path := filepath.Join(dir, name)
	file, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR|os.O_APPEND, 0o644)
	if err != nil {
		return nil, nil, fmt.Errorf("open %s log: %w", noun, err)
	}

	items, validLen, err := replayFrames(file, noun, decode)
	if err != nil {
		file.Close()
		return nil, nil, err
	}
	if info, statErr := file.Stat(); statErr == nil && validLen < info.Size() {
		// Drop exactly one incomplete trailing frame; the only mutation
		// recovery performs, fsynced before serving.
		if err := file.Truncate(validLen); err != nil {
			file.Close()
			return nil, nil, fmt.Errorf("truncate incomplete trailing %s frame: %w", noun, err)
		}
		if err := file.Sync(); err != nil {
			file.Close()
			return nil, nil, fmt.Errorf("sync %s log: %w", noun, err)
		}
	}
	// Flush the directory so the log file's own entry is durable, whether it
	// was just created or just truncated.
	if err := syncDir(dir); err != nil {
		file.Close()
		return nil, nil, fmt.Errorf("sync data directory: %w", err)
	}

	return &frameLog{file: file, dir: dir, noun: noun, unit: unit}, items, nil
}

// replayFrames scans the log and returns the decoded frames and the byte
// offset at which the log is known good. A torn trailing frame — a partial
// header, or a header whose payload never fully landed — ends the scan
// without error; any corruption before that offset is fatal.
func replayFrames[T any](file *os.File, noun string, decode func(payload []byte) (T, error)) ([]T, int64, error) {
	data, err := os.ReadFile(file.Name())
	if err != nil {
		return nil, 0, fmt.Errorf("read %s log: %w", noun, err)
	}

	var items []T
	pos := int64(0)
	for pos < int64(len(data)) {
		remaining := int64(len(data)) - pos
		if remaining < headerSize {
			break // torn partial header
		}
		payloadLen := int64(binary.BigEndian.Uint32(data[pos : pos+4]))
		if payloadLen <= 0 || payloadLen > MaxPayloadBytes {
			return nil, 0, corruption("corrupt %s frame header at offset %d", noun, pos)
		}
		frameEnd := pos + headerSize + payloadLen
		if frameEnd > int64(len(data)) {
			break // header landed but its payload did not: torn tail
		}
		payload := data[pos+headerSize : frameEnd]
		wantCRC := binary.BigEndian.Uint32(data[pos+4 : pos+headerSize])
		if crc32.ChecksumIEEE(payload) != wantCRC {
			return nil, 0, corruption("%s checksum mismatch at offset %d", noun, pos)
		}
		item, err := decode(payload)
		if err != nil {
			return nil, 0, corruption("illegal %s frame payload at offset %d: %v", noun, pos, err)
		}
		items = append(items, item)
		pos = frameEnd
	}
	return items, pos, nil
}

// appendFrame durably writes one already-encoded payload: the frame is
// written and fsynced before the call returns. Any write or sync failure
// poisons the log, so this call and every later one fail until restart. A
// payload that fails the size check returns ErrPayloadTooLarge before the
// log is touched and does not poison it.
func (l *frameLog) appendFrame(payload []byte) (err error) {
	if len(payload) > MaxPayloadBytes {
		return fmt.Errorf("%w: %s is %d bytes", ErrPayloadTooLarge, l.unit, len(payload))
	}

	frame := make([]byte, headerSize+len(payload))
	binary.BigEndian.PutUint32(frame[0:4], uint32(len(payload)))
	binary.BigEndian.PutUint32(frame[4:8], crc32.ChecksumIEEE(payload))
	copy(frame[headerSize:], payload)

	l.mu.Lock()
	defer l.mu.Unlock()
	if l.poisoned {
		return ErrPoisoned
	}
	defer func() {
		if err != nil {
			l.poisoned = true
		}
	}()

	if _, err = l.file.Write(frame); err != nil {
		return fmt.Errorf("write %s log: %w", l.noun, err)
	}
	if err = l.file.Sync(); err != nil {
		return fmt.Errorf("sync %s log: %w", l.noun, err)
	}
	return nil
}

// Poisoned reports whether the log has suffered an unrecoverable write error.
func (l *frameLog) Poisoned() bool {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.poisoned
}

// Close releases the log file.
func (l *frameLog) Close() error {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.file.Close()
}

package events

import (
	"errors"
	"time"
)

// maxCompareSegments caps how many segments a single comparison may split
// either window into. Requests needing more are rejected rather than
// truncated, so the response always covers the windows completely.
const maxCompareSegments = 10000

// CompareQuery selects two equal-length, half-open windows [Since, Until) and
// [BaselineSince, BaselineUntil) and divides them into intervals of Step,
// keeping only events that pass the same optional service, severity, and
// label filters Query uses.
type CompareQuery struct {
	Service       string
	Severity      string
	Labels        map[string]string
	BaselineSince time.Time
	BaselineUntil time.Time
	Since         time.Time
	Until         time.Time
	Step          time.Duration
}

// CompareSegment is one step-aligned slice of both windows, ordered from each
// window's start. Counts include segment start instants and exclude segment
// end instants; the final segment ends exactly at the window end even when
// that is short of a full step.
type CompareSegment struct {
	BaselineStart    time.Time
	BaselineEnd      time.Time
	ObservationStart time.Time
	ObservationEnd   time.Time
	BaselineCount    int
	ObservationCount int
}

// CompareResult holds the aggregate change between two windows plus every
// aligned segment. Ratio is the relative change (observation minus baseline
// over baseline); it is nil when the baseline total is zero.
type CompareResult struct {
	BaselineTotal    int
	ObservationTotal int
	Difference       int
	Ratio            *float64
	Segments         []CompareSegment
}

// Parameter problems a compare request can hit. The HTTP layer maps each to
// its own 400 message.
var (
	// ErrCompareStep reports a non-positive step; the HTTP layer bounds it
	// further to 1..86400 seconds.
	ErrCompareStep = errors.New("compare step must be positive")
	// ErrBaselineWindow reports a baseline whose start is not before its end.
	ErrBaselineWindow = errors.New("baseline window must start before it ends")
	// ErrObservationWindow reports an observation window whose start is not
	// before its end.
	ErrObservationWindow = errors.New("observation window must start before it ends")
	// ErrWindowLength reports two windows of different lengths.
	ErrWindowLength = errors.New("compare windows must have equal length")
	// ErrTooManySegments reports a request that needs more than
	// maxCompareSegments segments for either side.
	ErrTooManySegments = errors.New("compare windows require too many segments")
)

// Compare validates the windows and counts filtered events inside them using
// a single read of the timeline, so both sides, both totals, and every
// segment reflect one committed snapshot: a batch committed during the call
// is either fully present or fully absent.
func (t *Timeline) Compare(query CompareQuery) (CompareResult, error) {
	segments, err := ValidateCompareWindows(query)
	if err != nil {
		return CompareResult{}, err
	}

	filter := NewFilter(query.Service, query.Severity, query.Labels)

	baselineCounts := make([]int, len(segments))
	observationCounts := make([]int, len(segments))

	t.mu.RLock()
	for _, event := range t.events {
		if !filter.Matches(event) {
			continue
		}
		if i, ok := bucketIndex(event.At, query.BaselineSince, query.BaselineUntil, query.Step); ok {
			baselineCounts[i]++
		}
		if i, ok := bucketIndex(event.At, query.Since, query.Until, query.Step); ok {
			observationCounts[i]++
		}
	}
	t.mu.RUnlock()

	for i := range segments {
		segments[i].BaselineCount = baselineCounts[i]
		segments[i].ObservationCount = observationCounts[i]
	}

	result := CompareResult{Segments: segments}
	for i := range segments {
		result.BaselineTotal += baselineCounts[i]
		result.ObservationTotal += observationCounts[i]
	}
	result.Difference = result.ObservationTotal - result.BaselineTotal
	if result.BaselineTotal != 0 {
		ratio := float64(result.Difference) / float64(result.BaselineTotal)
		result.Ratio = &ratio
	}
	return result, nil
}

// ValidateCompareWindows enforces a positive step, strictly increasing
// windows (baseline first, then observation), equal lengths, and the per-side
// segment limit, then returns the aligned segment skeleton. Windows may
// overlap and are compared by absolute instant, so time zones are irrelevant.
func ValidateCompareWindows(query CompareQuery) ([]CompareSegment, error) {
	if query.Step <= 0 {
		return nil, ErrCompareStep
	}
	baselineLen := query.BaselineUntil.Sub(query.BaselineSince)
	observationLen := query.Until.Sub(query.Since)
	if baselineLen <= 0 {
		return nil, ErrBaselineWindow
	}
	if observationLen <= 0 {
		return nil, ErrObservationWindow
	}
	if baselineLen != observationLen {
		return nil, ErrWindowLength
	}

	// Ceiling division without an addition that could overflow for windows
	// close to the maximum representable duration.
	count := baselineLen / query.Step
	if baselineLen%query.Step != 0 {
		count++
	}
	if count > maxCompareSegments {
		return nil, ErrTooManySegments
	}

	out := make([]CompareSegment, count)
	for i := range out {
		baselineStart := query.BaselineSince.Add(query.Step * time.Duration(i))
		observationStart := query.Since.Add(query.Step * time.Duration(i))
		baselineEnd := baselineStart.Add(query.Step)
		if baselineEnd.After(query.BaselineUntil) {
			baselineEnd = query.BaselineUntil
		}
		observationEnd := observationStart.Add(query.Step)
		if observationEnd.After(query.Until) {
			observationEnd = query.Until
		}
		out[i] = CompareSegment{
			BaselineStart:    baselineStart,
			BaselineEnd:      baselineEnd,
			ObservationStart: observationStart,
			ObservationEnd:   observationEnd,
		}
	}
	return out, nil
}

// bucketIndex reports the zero-based segment, measured in whole steps from the
// window start, that contains at. The window is half-open: [start, end).
// A boundary aligned exactly with a segment start is counted in that segment;
// an instant equal to the window end is excluded.
func bucketIndex(at, start, end time.Time, step time.Duration) (int, bool) {
	if at.Before(start) || !at.Before(end) {
		return 0, false
	}
	offset := at.Sub(start)
	if offset < 0 {
		return 0, false
	}
	return int(offset / step), true
}

