package events

import (
	"fmt"
	"strings"
	"unicode/utf8"
)

// Label limits shared by ingestion and query filters. Names and values are
// trimmed of surrounding whitespace, keep their case, and must be non-empty
// afterwards; lengths are counted in Unicode code points.
const (
	// MaxLabelsPerEvent caps how many labels a single event may carry.
	MaxLabelsPerEvent = 32
	// MaxLabelNameRunes bounds a label name in Unicode code points.
	MaxLabelNameRunes = 64
	// MaxLabelValueRunes bounds a label value in Unicode code points.
	MaxLabelValueRunes = 256
	// MaxLabelFilters caps how many label conditions one query may carry.
	MaxLabelFilters = 32
)

// NormalizeLabels trims and validates a label set. A nil or empty set
// normalizes to nil, so the three "no labels" spellings (absent, null, {})
// are indistinguishable once stored. Names that differ only in surrounding
// whitespace collide and are rejected, as are over-long or empty names and
// values.
func NormalizeLabels(labels map[string]string) (map[string]string, error) {
	if len(labels) == 0 {
		return nil, nil
	}
	if len(labels) > MaxLabelsPerEvent {
		return nil, &ValidationError{Reason: fmt.Sprintf("event must not have more than %d labels", MaxLabelsPerEvent)}
	}
	normalized := make(map[string]string, len(labels))
	for name, value := range labels {
		name = strings.TrimSpace(name)
		value = strings.TrimSpace(value)
		if err := checkLabel(name, value); err != nil {
			return nil, err
		}
		if _, dup := normalized[name]; dup {
			return nil, &ValidationError{Reason: fmt.Sprintf("label name %q repeats after trimming", name)}
		}
		normalized[name] = value
	}
	return normalized, nil
}

// NormalizeLabelName applies the name half of the ingestion rules: trim
// surrounding whitespace and require a non-empty result within the rune
// limit. Group-by selectors and filter names go through the same gate as
// stored label names.
func NormalizeLabelName(name string) (string, error) {
	name = strings.TrimSpace(name)
	if name == "" {
		return "", &ValidationError{Reason: "label name must not be empty"}
	}
	if utf8.RuneCountInString(name) > MaxLabelNameRunes {
		return "", &ValidationError{Reason: fmt.Sprintf("label name must not exceed %d characters", MaxLabelNameRunes)}
	}
	return name, nil
}

// checkLabel enforces the name/value rules every label and every label
// filter condition follows. Callers pass already-trimmed arguments.
func checkLabel(name, value string) error {
	if name == "" {
		return &ValidationError{Reason: "label name must not be empty"}
	}
	if value == "" {
		return &ValidationError{Reason: "label value must not be empty"}
	}
	if utf8.RuneCountInString(name) > MaxLabelNameRunes {
		return &ValidationError{Reason: fmt.Sprintf("label name must not exceed %d characters", MaxLabelNameRunes)}
	}
	if utf8.RuneCountInString(value) > MaxLabelValueRunes {
		return &ValidationError{Reason: fmt.Sprintf("label value must not exceed %d characters", MaxLabelValueRunes)}
	}
	return nil
}

// ParseLabelConditions turns repeated "name=value" query parameters into a
// normalized condition set. The first '=' splits name from value; later
// equals signs belong to the value. Names and values follow the ingestion
// trimming and limit rules, and conditions whose names collide after
// trimming are rejected.
func ParseLabelConditions(raw []string) (map[string]string, error) {
	if len(raw) == 0 {
		return nil, nil
	}
	if len(raw) > MaxLabelFilters {
		return nil, &ValidationError{Reason: fmt.Sprintf("at most %d label filters are allowed", MaxLabelFilters)}
	}
	conditions := make(map[string]string, len(raw))
	for _, item := range raw {
		name, value, ok := strings.Cut(item, "=")
		if !ok {
			return nil, &ValidationError{Reason: "label filter must use the form name=value"}
		}
		name = strings.TrimSpace(name)
		value = strings.TrimSpace(value)
		if err := checkLabel(name, value); err != nil {
			return nil, err
		}
		if _, dup := conditions[name]; dup {
			return nil, &ValidationError{Reason: fmt.Sprintf("label filter %q repeats", name)}
		}
		conditions[name] = value
	}
	return conditions, nil
}

// NormalizeLabelConditions trims and validates a decoded object of label
// conditions: the JSON-object counterpart to ParseLabelConditions. The
// strict object shape (string values, no duplicate JSON keys) is enforced by
// DecodeLabelsObject; here names and values pass the same trimming and limit
// rules, and names colliding after trimming are rejected.
func NormalizeLabelConditions(raw map[string]string) (map[string]string, error) {
	if len(raw) == 0 {
		return nil, nil
	}
	if len(raw) > MaxLabelFilters {
		return nil, &ValidationError{Reason: fmt.Sprintf("at most %d label filters are allowed", MaxLabelFilters)}
	}
	conditions := make(map[string]string, len(raw))
	for name, value := range raw {
		name = strings.TrimSpace(name)
		value = strings.TrimSpace(value)
		if err := checkLabel(name, value); err != nil {
			return nil, err
		}
		if _, dup := conditions[name]; dup {
			return nil, &ValidationError{Reason: fmt.Sprintf("label filter %q repeats", name)}
		}
		conditions[name] = value
	}
	return conditions, nil
}

// labelsMatch reports whether a stored label set satisfies every condition.
// An event missing a conditioned label never matches, and comparison is
// case-sensitive on both names and values.
func labelsMatch(labels, conditions map[string]string) bool {
	for name, want := range conditions {
		got, ok := labels[name]
		if !ok || got != want {
			return false
		}
	}
	return true
}

package logfile

import (
	"fmt"

	"github.com/cocosolocoder/signalroom/internal/incidents"
)

// incidentLogName is the append-only record log for incidents. It sits next
// to events.log in the locked data directory and uses the same
// length-prefixed, CRC-checked frame layout, so the durability and recovery
// rules are identical: fsync before acknowledging, trim only a torn tail,
// and refuse to start on any other corruption.
const incidentLogName = "incidents.log"

// IncidentLog is the concurrency-safe durable writer for incident records.
// It is independent from the event log: an incident write failure poisons
// only incident handling, exactly as an event write failure poisons only
// event ingestion.
type IncidentLog struct {
	*frameLog
}

// OpenIncidentLog opens (creating if absent) the incident log inside an
// already-locked data directory, replays its records, and truncates at most
// one incomplete trailing frame. A corrupt frame in the middle, or a
// complete frame containing illegal data, is fatal and leaves the file
// untouched. Call it only after Open has acquired the directory lock.
func OpenIncidentLog(dir string) (*IncidentLog, []incidents.Record, error) {
	if dir == "" {
		return nil, nil, fmt.Errorf("data directory is required")
	}
	base, records, err := openFrameLog(dir, incidentLogName, "incident", "incident record", incidents.DecodeRecord)
	if err != nil {
		return nil, nil, err
	}
	return &IncidentLog{frameLog: base}, records, nil
}

// AppendRecord durably writes one record: the frame is written and fsynced
// before the call returns. Any write or sync failure poisons the log so that
// this call and every later one fail until restart.
func (l *IncidentLog) AppendRecord(record incidents.Record) error {
	payload, err := incidents.MarshalRecord(record)
	if err != nil {
		return fmt.Errorf("encode incident record: %w", err)
	}
	return l.appendFrame(payload)
}

