297			t.Fatal("rejected second instance must not change data")
298		}
299	
300		if err := first.Close(); err != nil {
301			t.Fatalf("close first: %v", err)
302		}
303	
304		third, batches, err := Open(dir)
305		if err != nil {
306			t.Fatalf("restart after clean exit must succeed: %v", err)
307		}
308		defer third.Close()
