// openFrameLog opens (creating if absent) the named log inside an
// already-locked data directory and replays its frames without modifying the
// file. decode translates every complete frame's payload and validate runs
// once over all decoded frames; either one rejecting a complete frame is
// fatal (the error wraps ErrFrameRecovery) and leaves the file untouched. A
// torn trailing frame ends the replay without being decoded or validated.
// The caller must pass the returned handle and goodLen to
// finishFrameRecovery, which trims that tail, only after every other
// startup-time recovery step has succeeded.
func openFrameLog[T any](dir, name, noun, unit string, decode func(payload []byte) (T, error), validate func(items []T) error) (*frameLog, []T, int64, error) {
	path := filepath.Join(dir, name)
	file, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR|os.O_APPEND, 0o644)
	if err != nil {
		return nil, nil, 0, fmt.Errorf("open %s log: %w", noun, err)
	}

	items, validLen, err := replayFrames(file, noun, decode)
	if err != nil {
		file.Close()
		return nil, nil, 0, fmt.Errorf("%w: %v", ErrFrameRecovery, err)
	}
	if validate != nil {
		if err := validate(items); err != nil {
			file.Close()
			return nil, nil, 0, fmt.Errorf("%w: %v", ErrFrameRecovery, err)
		}
	}
	return &frameLog{file: file, dir: dir, noun: noun, unit: unit}, items, validLen, nil
}

// finishFrameRecovery completes startup for a log opened by openFrameLog:
// it truncates at most one incomplete trailing frame (the only mutation
// recovery performs, fsynced before serving) and flushes the directory so the
// file's own entry is durable whether it was just created or just truncated.
// Call it only after every recovered frame and every other data source have
// been validated, so a startup that is going to fail never alters the log.
func finishFrameLog(l *frameLog, validLen int64) error {
	if info, statErr := l.file.Stat(); statErr == nil && validLen < info.Size() {
		if err := l.file.Truncate(validLen); err != nil {
			return fmt.Errorf("truncate incomplete trailing %s frame: %w", l.noun, err)
		}
		if err := l.file.Sync(); err != nil {
			return fmt.Errorf("sync %s log: %w", l.noun, err)
		}
	}
	if err := syncDir(l.dir); err != nil {
		return fmt.Errorf("sync data directory: %w", err)
	}
	return nil
}

